import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

function parseThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const thresholds = {};
  for (const str of thresholdStrings) {
    const [metric, minStr] = str.split('=');
    if (!metric || minStr === undefined) {
      throw {
        type: 'usage_error',
        message: `Malformed threshold: "${str}". Use format: metric=<number> (e.g., exact_match=0.9)`
      };
    }

    const min = parseFloat(minStr);
    if (isNaN(min) || min < 0 || min > 1) {
      throw {
        type: 'usage_error',
        message: `Invalid threshold value: "${minStr}" for metric "${metric}". Must be a number between 0 and 1.`
      };
    }

    thresholds[metric] = min;
  }

  return thresholds;
}

function validateThresholds(thresholds, evaluations) {
  if (!thresholds) {
    return null;
  }

  const validMetricIds = new Set(evaluations.map((e) => e.id));

  for (const metricId of Object.keys(thresholds)) {
    if (!validMetricIds.has(metricId)) {
      const availableIds = Array.from(validMetricIds).join(', ');
      throw {
        type: 'usage_error',
        message: `Unknown metric: "${metricId}". Available metrics: ${availableIds}`
      };
    }
  }

  const thresholdResults = [];
  for (const [metricId, min] of Object.entries(thresholds)) {
    const metric = evaluations.find((e) => e.id === metricId);
    const score = metric.score;
    const passed = score !== null && score >= min;

    thresholdResults.push({
      metric: metricId,
      min,
      score,
      passed
    });
  }

  return thresholdResults;
}

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

