  const result = parseThresholds(['exact_match=0.9', 'toxicity=0.8']);
  expect(result).toEqual({ exact_match: 0.9, toxicity: 0.8 });
});

it('rejects malformed thresholds', () => {
  expect(() => parseThresholds(['exact_match'])).toThrow({
    type: 'usage_error'
  });
  expect(() => parseThresholds(['exact_match=invalid'])).toThrow({
    type: 'usage_error'
  });
  expect(() => parseThresholds(['exact_match=1.5'])).toThrow({
    type: 'usage_error'
  });
});

it('validates thresholds against evaluations', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello', 'friendly world'],
    references: ['hello', 'friendly world']
  });
  const result = validateThresholds(
    { exact_match: 0.9, toxicity: 0.9 },
    evaluations
  );
  expect(result).toHaveLength(2);
  expect(result[0]).toMatchObject({
    metric: 'exact_match',
    min: 0.9,
    passed: true
  });
  expect(result[1]).toMatchObject({
    metric: 'toxicity',
    min: 0.9,
    passed: true
  });
});

it('fails thresholds when score is null', () => {
  const evaluations = runEvaluations({
    outputs: [],
    references: []
  });
  const result = validateThresholds({ exact_match: 0.5 }, evaluations);
  expect(result[0]).toMatchObject({
    metric: 'exact_match',
    min: 0.5,
    score: null,
    passed: false
  });
});

it('rejects unknown metric in thresholds', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  expect(() => validateThresholds({ unknown_metric: 0.5 }, evaluations)).toThrow({
    type: 'usage_error'
  });
});

it('includes thresholds in generated report', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const thresholds = parseThresholds(['exact_match=0.9']);
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds,
    generatedAt: '2024-01-01T00:00:00.000Z'
  });
  expect(report.passed).toBe(true);
  expect(report.thresholds).toHaveLength(1);
  expect(report.thresholds[0]).toMatchObject({
    metric: 'exact_match',
    min: 0.9,
    passed: true
  });
});

it('marks report as failed when threshold not met', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello', 'World'],
    references: ['Goodbye', 'Moon']
  });
  const thresholds = parseThresholds(['exact_match=0.9']);
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds,
    generatedAt: '2024-01-01T00:00:00.000Z'
  });
  expect(report.passed).toBe(false);
  expect(report.thresholds[0].passed).toBe(false);
});

