import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport,
  parseThresholds,
  validateThresholds
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('parses thresholds from string array', () => {
    const { parseThresholds } = await import('./index.js');
    const result = parseThresholds(['exact_match=0.9', 'toxicity=0.8']);
    expect(result).toEqual({ exact_match: 0.9, toxicity: 0.8 });
  });

  it('rejects malformed thresholds', () => {
    const { parseThresholds } = await import('./index.js');
    expect(() => parseThresholds(['exact_match'])).toThrow({
      type: 'usage_error'
    });
    expect(() => parseThresholds(['exact_match=invalid'])).toThrow({
      type: 'usage_error'
    });
    expect(() => parseThresholds(['exact_match=1.5'])).toThrow({
      type: 'usage_error'
    });
  });

  it('validates thresholds against evaluations', () => {
    const { validateThresholds } = await import('./index.js');
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const result = validateThresholds(
      { exact_match: 0.9, toxicity: 0.9 },
      evaluations
    );
    expect(result).toHaveLength(2);
    expect(result[0]).toMatchObject({
      metric: 'exact_match',
      min: 0.9,
      passed: true
    });
    expect(result[1]).toMatchObject({
      metric: 'toxicity',
      min: 0.9,
      passed: true
    });
  });

  it('fails thresholds when score is null', () => {
    const { validateThresholds } = await import('./index.js');
    const evaluations = runEvaluations({
      outputs: [],
      references: []
    });
    const result = validateThresholds({ exact_match: 0.5 }, evaluations);
    expect(result[0]).toMatchObject({
      metric: 'exact_match',
      min: 0.5,
      score: null,
      passed: false
    });
  });

  it('rejects unknown metric in thresholds', () => {
    const { validateThresholds } = await import('./index.js');
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    expect(() => validateThresholds({ unknown_metric: 0.5 }, evaluations)).toThrow({
      type: 'usage_error'
    });
  });

  it('includes thresholds in generated report', () => {
    const { parseThresholds, validateThresholds } = await import('./index.js');
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const thresholds = parseThresholds(['exact_match=0.9']);
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds,
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      min: 0.9,
      passed: true
    });
  });

  it('marks report as failed when threshold not met', () => {
    const { parseThresholds } = await import('./index.js');
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['Goodbye', 'Moon']
    });
    const thresholds = parseThresholds(['exact_match=0.9']);
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds,
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
  });
});

